oxy_webhelp_navlinks = {"everpure_flasharray_setup-d39536e52397":{"topics":[{"title":"Everpure FlashArray requirements","shortdesc":"<p class=\"shortdesc\">Everpure FlashArray volume protection has specific requirements for Purity\/\/FA         version, authentication, and network connectivity.<\/p>","href":"saas\/everpure_flasharray_requirements.html","attributes":{"data-id":"everpure_flasharray_requirements"},"menu":{"hasChildren":false},"tocID":"everpure_flasharray_requirements-d39536e52411","topics":[]},{"title":"Adding an Everpure FlashArray","shortdesc":"<p class=\"shortdesc\">Add an Everpure FlashArray to <span class=\"ph\">RSC<\/span> to discover its Protection         Groups and volumes for protection.<\/p>","href":"saas\/everpure_adding_flasharray.html","attributes":{"data-id":"everpure_adding_flasharray"},"menu":{"hasChildren":false},"tocID":"everpure_adding_flasharray-d39536e52422","topics":[]},{"title":"Everpure FlashArray connection management","shortdesc":"<p class=\"shortdesc\">After you add an Everpure FlashArray to <span class=\"ph\">RSC<\/span>, three operations are         available for managing the FlashArray connection over its lifecycle: refresh, edit, and         delete.<\/p>","href":"saas\/everpure_flasharray_connection_management.html","attributes":{"data-id":"everpure_flasharray_connection_management"},"menu":{"hasChildren":false},"tocID":"everpure_flasharray_connection_management-d39536e52436","topics":[]},{"title":"Assigning SLA Domains to Everpure FlashArray Protection Groups and volumes","shortdesc":"<p class=\"shortdesc\">Assign an SLA Domain to an Everpure FlashArray Protection Group or standalone         volume. You can also exclude individual volumes from a Protection Group's         snapshots.<\/p>","href":"saas\/everpure_assigning_sla_domains.html","attributes":{"data-id":"everpure_assigning_sla_domains"},"menu":{"hasChildren":false},"tocID":"everpure_assigning_sla_domains-d39536e52450","topics":[]},{"title":"Excluding volumes from an Everpure FlashArray Protection Group","shortdesc":"<p class=\"shortdesc\">Exclude specific volumes from snapshots of a Protection Group. Excluded volumes         remain members of the Protection Group but are not included in backups or recovery         operations.<\/p>","href":"saas\/everpure_excluding_volumes.html","attributes":{"data-id":"everpure_excluding_volumes"},"menu":{"hasChildren":false},"tocID":"everpure_excluding_volumes-d39536e52461","topics":[]}]}};